// Adds a hover definition to the first use of each glossary term on the page (data from data/glossary.json,
// generated by adamas.glossary). Skips code, scripts, form controls, and graphics so nothing interactive changes.
const SKIP = new Set(['SCRIPT', 'STYLE', 'CODE', 'PRE', 'BUTTON', 'SELECT', 'OPTION', 'TEXTAREA', 'INPUT', 'SVG', 'CANVAS', 'A', 'ABBR', 'H1', 'NAV']);
export async function glossary(base = '.') {
  if (document.querySelector('.gterm')) return;            // the glossary page explains itself
  let G; try { G = await (await fetch(`${base}/data/glossary.json`)).json(); } catch { return; }
  const keys = Object.keys(G).sort((a, b) => b.length - a.length), esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(`(?<![\\w-])(${keys.map(esc).join('|')})(?![\\w-])`), seen = new Set([...document.querySelectorAll('abbr.gl')].map(a => a.textContent)), root = document.querySelector('main');
  if (!root) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, { acceptNode: n => { for (let p = n.parentElement; p && p !== root; p = p.parentElement) if (SKIP.has(p.tagName.toUpperCase())) return NodeFilter.FILTER_REJECT; return NodeFilter.FILTER_ACCEPT; } });
  const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) {
    const m = node.nodeValue.match(re); if (!m || seen.has(m[1])) continue; seen.add(m[1]);
    const i = m.index, abbr = document.createElement('abbr'); abbr.className = 'gl'; abbr.textContent = m[1];
    abbr.dataset.tip = `${m[1]}: ${G[m[1]].full}. ${G[m[1]].def}`; abbr.title = `${G[m[1]].full}`;
    const rest = node.splitText(i); rest.nodeValue = rest.nodeValue.slice(m[1].length); node.parentNode.insertBefore(abbr, rest);
  }
}
